package com.careflow.hospital.patients;
import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/patients/me/data")@PreAuthorize("hasRole('PATIENT')")
public class PatientDataController {private final JdbcTemplate jdbc;private final PatientRepository patients;public PatientDataController(JdbcTemplate j,PatientRepository p){jdbc=j;patients=p;}
 @GetMapping("/export")public ResponseEntity<Map<String,Object>> export(Authentication auth){UUID userId=UUID.fromString(auth.getName());var patient=patients.findByUserId(userId).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));UUID id=patient.getId();var data=new LinkedHashMap<String,Object>();data.put("exportedAt",Instant.now());data.put("profile",jdbc.queryForMap("select patient_id,patient_number,full_name,date_of_birth,phone,gender,address,emergency_contact,preferred_language,created_at from patient where patient_id=?",id));data.put("appointments",jdbc.queryForList("select appointment_number,doctor_id,starts_at,ends_at,status,cancellation_reason,created_at from appointment where patient_id=? order by created_at",id));data.put("clinicalRecords",jdbc.queryForList("select appointment_id,record_type,summary,created_at from clinical_record where patient_id=? order by created_at",id));data.put("labOrders",jdbc.queryForList("select test_code,status,result_summary,created_at,updated_at from lab_order where patient_id=? order by created_at",id));data.put("invoices",jdbc.queryForList("select appointment_id,amount_minor,currency,status,created_at from invoice where patient_id=? order by created_at",id));data.put("notifications",jdbc.queryForList("select channel,subject,body,status,created_at,read_at from notification where user_id=? order by created_at",userId));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=careflow-data-export.json").header(HttpHeaders.CACHE_CONTROL,"no-store").body(data);}
}
